 Transform room;Camera closeCamera;Canvas canvas;GameObject sheet;RectTransform badge;Text badgeText,title,instruction,feedback,volume,steps,result;FactoryDesktopIcon badgeIcon,badgeFace;Image badgeGlow;Transform[] items=new Transform[5];Transform cylinderLiquid,flaskLiquid;Mesh flaskMesh;Transform[] caps=new Transform[5];LineRenderer stream;Material glass,liquid,metal,blue,white,ink,red;int held=-1;bool pouring,approaching;float blockUntil,mixAngle,lastAngle;bool angleValid;Vector2 pointer;string hint="";LineRenderer outline,halo;TextMesh cylinderReading,flaskReading,meterReading;Button reset,rinse;GameObject decisionPanel;LineRenderer cable;bool probeRinsed;float measurementTime;
