 public bool ConsumePointer(Vector2 p){if(BlocksWorldInput)return true;if(!Unlocked||computer.IsOpen)return false;var c=ScreenPosition;if(new Rect(c.x-65,c.y-45,130,90).Contains(p)){Request();return true;}return false;}
