 public void Close(){Release(false);IsOpen=false;sheet.SetActive(false);closeCamera.enabled=false;explorer.view.enabled=true;blockUntil=Time.unscaledTime+.2f;explorer.LockForComputer(false);if(EventSystem.current)EventSystem.current.SetSelectedGameObject(null);}
 void HandlePointer(){
  bool down=Input.GetMouseButtonDown(0),pressed=Input.GetMouseButton(0),up=Input.GetMouseButtonUp(0);pointer=Input.mousePosition;
  if(Input.touchCount>0){var t=Input.GetTouch(0);pointer=t.position;down=t.phase==TouchPhase.Began;pressed=t.phase==TouchPhase.Moved||t.phase==TouchPhase.Stationary||down;up=t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled;}
  // Explicit regions avoid a stale EventSystem hover after clicking Reset.
  bool overHud=pointer.y>Screen.height*(1-134f/800)||pointer.y<Screen.height*121f/800;
  if(down&&held<0&&!Completed&&!overHud&&Step<4){Physics.SyncTransforms();var ray=closeCamera.ScreenPointToRay(pointer);if(Physics.Raycast(ray,out var hit,100,1<<30)){for(int i=0;i<5;i++)if(hit.transform==items[i]||hit.transform.IsChildOf(items[i])){held=i;hint="";angleValid=false;if(caps[i]){caps[i].SetParent(room,false);caps[i].localPosition=home[i]+new Vector3(.42f,.07f,-.5f);}break;}}}
  if(held<0)return;
  var plane=new Plane(Vector3.up,room.position+Vector3.up*.8f);if(!plane.Raycast(closeCamera.ScreenPointToRay(pointer),out float distance))return;var local=closeCamera.ScreenPointToRay(pointer).GetPoint(distance)-room.position;local.x=Mathf.Clamp(local.x,-3.7f,3.7f);local.z=Mathf.Clamp(local.z,-1.2f,1.4f);
  if(pressed){
   if(Step==2&&held==3){var center=closeCamera.WorldToScreenPoint(room.position+home[3]+Vector3.up*.6f);var delta=pointer-(Vector2)center;float radius=delta.magnitude/(Screen.height/800f);float angle=Mathf.Atan2(delta.y,delta.x)*Mathf.Rad2Deg;if(radius>35&&radius<180){if(angleValid){float change=Mathf.DeltaAngle(lastAngle,angle);if(Mathf.Abs(change)<65)mixAngle+=change;}lastAngle=angle;angleValid=true;}else angleValid=false;items[3].localPosition=home[3]+new Vector3(Mathf.Clamp(delta.x/180,-.28f,.28f),.08f,Mathf.Clamp(delta.y/180,-.28f,.28f));items[3].localRotation=Quaternion.Euler(4*Mathf.Sin(Time.time*4),0,5*Mathf.Cos(Time.time*4));if(MixTurns>=2){Step=3;hint="Проба однородна. Промой электрод, затем опусти его в стакан.";Release(false);}return;}
   int receiver=Step==0?2:3;bool over=Vector2.Distance(new Vector2(local.x,local.z),new Vector2(home[receiver].x,home[receiver].z))<.72f;
   if(Step==3&&held==4&&over){if(!probeRinsed){hint="Сначала промой электрод кнопкой у прибора.";return;}items[4].localPosition=home[3]+new Vector3(0,.1f,0);items[4].localRotation=Quaternion.identity;measurementTime+=Time.deltaTime;meterReading.text="pH\n"+Mathf.Lerp(4.01f,2.72f,Mathf.Clamp01(measurementTime/1.8f)).ToString("0.00");if(measurementTime>=1.8f){MeasuredPh=2.72f;Step=4;hint="pH стабилен. Сравни с картой контроля и выбери действие.";Release(false);}return;}
   bool allowed=Step==0&&held==0||Step==1&&held==2;
   if(over&&allowed){pouring=true;float vesselHeight=held==2?1.5f:1.18f;var tilt=Quaternion.Euler(0,0,-65);var mouth=home[receiver]+new Vector3(0,(receiver==2?1.5f:1.12f)+.28f,0);items[held].localRotation=tilt;items[held].localPosition=mouth-tilt*(Vector3.up*vesselHeight);stream.enabled=true;stream.SetPosition(0,items[held].TransformPoint(Vector3.up*vesselHeight));float surface=receiver==2?.05f+SampleMl/50*1.25f:.05f+FlaskMl/50*.85f;stream.SetPosition(1,room.position+home[receiver]+Vector3.up*surface);stream.startColor=stream.endColor=new Color(.88f,.8f,.38f,.8f);
    if(Step==0){float rate=SampleMl>=24?3:8;SampleMl=Mathf.Min(30,SampleMl+rate*Time.deltaTime);if(SampleMl>=30){Step=1;hint="30 мл — готово! Наливание остановлено. Перенеси порцию в измерительный стакан.";Release(false);}}else if(Step==1){float transfer=Mathf.Min(SampleMl,18*Time.deltaTime);SampleMl-=transfer;FlaskMl+=transfer;if(SampleMl<.01f){SampleMl=0;Step=2;hint="Осторожно перемешай пробу двумя круговыми движениями.";Release(false);}}
