 void SetFlaskLiquid(){float height=FlaskMl/50f*.85f;flaskLiquid.gameObject.SetActive(height>.001f);if(height<=.001f)return;flaskLiquid.localPosition=Vector3.up*.05f;flaskLiquid.localScale=Vector3.one;var vertices=new Vector3[66];var triangles=new int[384];float top=.37f;for(int i=0;i<32;i++){float a=i*Mathf.PI/16;vertices[i]=new Vector3(Mathf.Sin(a)*.35f,0,Mathf.Cos(a)*.35f);vertices[32+i]=new Vector3(Mathf.Sin(a)*top,height,Mathf.Cos(a)*top);int next=(i+1)%32;int k=i*12;triangles[k]=i;triangles[k+1]=next;triangles[k+2]=32+i;triangles[k+3]=next;triangles[k+4]=32+next;triangles[k+5]=32+i;triangles[k+6]=64;triangles[k+7]=i;triangles[k+8]=next;triangles[k+9]=65;triangles[k+10]=32+next;triangles[k+11]=32+i;}vertices[65]=Vector3.up*height;flaskMesh.Clear();flaskMesh.vertices=vertices;flaskMesh.triangles=triangles;flaskMesh.RecalculateNormals();}
