 Material Mat(string name,Color color,bool transparent=false){var m=new Material(Shader.Find(transparent?"Sprites/Default":"Standard"));m.name=name;m.color=color;m.SetFloat("_Glossiness",transparent?.85f:.22f);if(transparent){m.SetFloat("_Mode",3);m.SetInt("_SrcBlend",(int)UnityEngine.Rendering.BlendMode.SrcAlpha);m.SetInt("_DstBlend",(int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);m.SetInt("_ZWrite",0);m.EnableKeyword("_ALPHABLEND_ON");m.renderQueue=3000;}return m;}
