  for(int i=0;i<48;i++){float a=i*Mathf.PI/24,b=(i+1)*Mathf.PI/24;Tube(root,new Vector3(Mathf.Sin(a)*rs[rs.Length-1],ys[ys.Length-1],Mathf.Cos(a)*rs[rs.Length-1]),new Vector3(Mathf.Sin(b)*rs[rs.Length-1],ys[ys.Length-1],Mathf.Cos(b)*rs[rs.Length-1]),.012f,white);}
