public static class FactoryBeaconArt {
 static Sprite glow;
 public static Sprite Glow(){if(glow)return glow;var t=new Texture2D(64,64,TextureFormat.RGBA32,false);for(int y=0;y<64;y++)for(int x=0;x<64;x++){float d=Vector2.Distance(new Vector2(x+.5f,y+.5f),new Vector2(32,32))/32;float a=Mathf.Pow(Mathf.Clamp01(1-d),1.3f);t.SetPixel(x,y,new Color(1,1,1,a));}t.Apply();glow=Sprite.Create(t,new Rect(0,0,64,64),new Vector2(.5f,.5f));return glow;}
}
